private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null || node.left == null) return node;
    TreeNode<T> newRoot = node.left;
    TreeNode<T> transfer = newRoot.right;
    newRoot.right = node;
    node.left = transfer;
    if (node.parent != null) {
        if (node.parent.left == node) node.parent.left = newRoot;
        else if (node.parent.right == node) node.parent.right = newRoot;
    }
    newRoot.parent = node.parent;
    node.parent = newRoot;
    if (transfer != null) transfer.parent = node;
    return newRoot;
}<|return|>

