public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    Path root = file.toPath();
    try {
        java.nio.file.Files.walkFileTree(root, new java.nio.file.SimpleFileVisitor<Path>() {
            @Override
            public java.nio.file.FileVisitResult visitFile(Path f, java.nio.file.attribute.BasicFileAttributes attrs) {
                f.toFile().deleteOnExit();
                return java.nio.file.FileVisitResult.CONTINUE;
            }

            @Override
            public java.nio.file.FileVisitResult postVisitDirectory(Path dir, IOException exc) throws IOException {
                if (exc != null) {
                    throw exc;
                }
                dir.toFile().deleteOnExit();
                return java.nio.file.FileVisitResult.CONTINUE;
            }
        });
    } catch (IOException e) {
        throw new IOException("Failed to schedule deletion on exit for " + file, e);
    }
}<|return|>

