    if (file.isDirectory()) {
        File[] children = file.listFiles();
        if (children != null) {
            for (File child : children) {
                forceDeleteOnExit(child);
            }
        }
    }
    try {
        file.deleteOnExit();
    } catch (SecurityException e) {
        throw new IOException("Unable to schedule deletion for " + file, e);
    }
