@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Target graph and result map must not be null.");
    }
    try {
        // Create two vertex sets of equal size for a simple complete bipartite K2,2
        int leftCount = 2;
        int rightCount = 2;
        List<V> leftVertices = new ArrayList<>();
        List<V> rightVertices = new ArrayList<>();

        // Add left side vertices
        for (int i = 0; i < leftCount; i++) {
            @SuppressWarnings("unchecked")
            V v = (V) Integer.valueOf(i);
            target.addVertex(v);
            resultMap.put("L" + i, v);
            leftVertices.add(v);
        }

        // Add right side vertices
        for (int j = 0; j < rightCount; j++) {
            @SuppressWarnings("unchecked")
            V v = (V) Integer.valueOf(leftCount + j);
            target.addVertex(v);
            resultMap.put("R" + j, v);
            rightVertices.add(v);
        }

        // Connect every left vertex to every right vertex
        for (V l : leftVertices) {
            for (V r : rightVertices) {
                target.addEdge(l, r);
            }
        }
    } catch (ClassCastException e) {
        throw new RuntimeException("Vertex type V must support casting from Integer for this generator", e);
    } catch (Exception e) {
        throw new RuntimeException("Unexpected error while generating complete bipartite graph", e);
